import {nativeAnchors,ocrAnchors,translatePDFPage,MAX_LAYOUT_PAGES} from './layout-translation.js';
const $=q=>document.querySelector(q);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const languageOptions=(selected)=>[['zh','中文'],['en','English'],['de','Deutsch']].map(([v,t])=>`<option value="${v}" ${v===selected?'selected':''}>${t}</option>`).join('');
export function createLayoutTranslation({rpc,dialog,toast,run,progress,state,cloud,configure,rangePages,download,setAbort}){
 let draft=null;
 async function start(){
  if(state().busy)return;if(!cloud.key||!cloud.model){if(!await configure())return;}
  const known=cloud.models.find(m=>m.id===cloud.model);if(known&&!known.modalities?.includes('file')){toast('Bitte in den OpenRouter-Einstellungen ein Modell mit nativer PDF-Unterstützung wählen.',true);if(!await configure())return;}
  const answer=await dialog('PDF mit Layout übersetzen',`<p>Für Zertifikate, Formulare und kurze Dokumente. Text wird übersetzt und an ähnlicher Position auf dem ursprünglichen Seitenbild eingesetzt.</p><label class="field-label">Seitenbereich (leer = alle · höchstens ${MAX_LAYOUT_PAGES})</label><input name="range" value="${esc($('#textRange')?.value||'')}" placeholder="z. B. 1-3"><div class="form-row"><label><span class="field-label">Von</span><select name="source">${languageOptions(draft?.source||'zh')}</select></label><label><span class="field-label">Nach</span><select name="target">${languageOptions(draft?.target||'en')}</select></label></div><label class="check"><input type="checkbox" name="ocr" checked> Bei Scans lokale OCR als zusätzliche Positionshilfe verwenden</label><div class="info-box">Die ausgewählten sichtbaren Seiten werden als PDF an <strong>OpenRouter und den Anbieter von ${esc(cloud.model)}</strong> gesendet, einschließlich Bildern, Stempeln und Unterschriften. Pro Seite erfolgt eine kostenpflichtige Modellanfrage. ${cloud.zdr?'ZDR ist aktiviert.':''}</div><p class="small-note">Die PDF wird für den Versand aus den sichtbaren Seiten neu erstellt, ohne versteckte Inhalte und Anhänge. Benötigt ein Modell mit nativer PDF-Verarbeitung und strukturierter Ausgabe. Stempel und Logos sollen erhalten bleiben; Positionen und Übersetzungen bitte in der Vorschau prüfen. Die Kopie erhält einen Übersetzungshinweis und übernimmt keine digitale Signatur.</p>`,{confirm:'PDF senden & übersetzen'});
  if(!answer)return;let indices;try{indices=rangePages(answer.range);if(indices.length>MAX_LAYOUT_PAGES)throw Error(`Bitte höchstens ${MAX_LAYOUT_PAGES} Seiten wählen.`);if(answer.source===answer.target)throw Error('Bitte unterschiedliche Sprachen wählen.');}catch(e){return toast(e.message,true);}
  draft={pages:[],source:answer.source,target:answer.target,total:indices.length,requested:indices.map(i=>i+1),complete:false,error:'',name:state().name.replace(/\.pdf$/i,''),cost:0};
  await run(async()=>{
   const abort=new AbortController();setAbort(abort);let ocrWorker;
   try{for(const [n,index] of indices.entries()){
    abort.signal.throwIfAborted();progress(`PDF vorbereiten · Seite ${n+1}/${indices.length} …`);
    const page=await rpc('translationPage',{index,dpi:144});let anchors=nativeAnchors(page.layout);const notes=[];
    if(answer.ocr&&anchors.reduce((n,a)=>n+a.source.length,0)<40){
     try{
      if(!ocrWorker){progress('Lokale Positionshilfe für Scans wird geladen …');const {default:Tesseract}=await import('./vendor/ocr/tesseract.esm.min.js');const base=new URL('./vendor/',location.href);ocrWorker=await Tesseract.createWorker(answer.source==='zh'?'chi_sim+eng':answer.source==='de'?'deu+eng':'eng',1,{workerPath:new URL('./ocr-worker.js',location.href).href,corePath:new URL('ocr/tesseract-core-lstm.wasm.js',base).href,langPath:new URL('lang/',base).href,workerBlobURL:false,cacheMethod:'none',errorHandler:()=>{}});}
      progress(`OCR-Positionshilfe · Seite ${n+1}/${indices.length} …`);const result=await ocrWorker.recognize(new Blob([page.image],{type:'image/png'}),{}, {text:true,blocks:true});anchors=ocrAnchors(result.data,page.pixelWidth,page.pixelHeight);
     }catch{notes.push('Lokale OCR-Positionshilfe nicht verfügbar. Die Textpositionen wurden ausschließlich von der KI ermittelt.');}
    }
    abort.signal.throwIfAborted();progress(`PDF mit KI übersetzen · Seite ${n+1}/${indices.length} …`);
    const result=await translatePDFPage({pdf:page.pdf,width:page.width,height:page.height,anchors,key:cloud.key,model:cloud.model,source:answer.source,target:answer.target,zdr:cloud.zdr,signal:abort.signal});
    draft.cost+=result.cost;draft.pages.push({page:page.page,width:page.width,height:page.height,image:page.image,blocks:result.blocks,warnings:[...notes,...result.warnings]});
   }draft.complete=true;
   }catch(e){draft.error=abort.signal.aborted?'Abgebrochen; bereits gesendete Anfragen können berechnet werden.':e.message;throw Error(draft.error);}
   finally{await ocrWorker?.terminate();}
  },'PDF-Übersetzung wird vorbereitet …');
  if(draft.pages.length)await review();
 }
 async function review(){
  if(!draft?.pages.length)return toast('Es ist noch kein Layout-Entwurf vorhanden.');
  let pi=0,selected=-1,urls=[],renderSeq=0,shown=null;const snapshot=draft;
  const body=`${!snapshot.complete?`<div class="info-box warning">Unvollständig: ${snapshot.pages.length} von ${snapshot.total} Seiten übersetzt. ${esc(snapshot.error)} Nicht bearbeitete Seiten sind nicht Teil des Exports.</div>`:''}<p>Vergleiche die Übersetzung mit dem Original. Klicke auf einen Rahmen oder wähle ein Textfeld. Korrekturen bleiben lokal und lösen keine weiteren KI-Anfragen aus.</p><div class="layout-review-toolbar"><label>Seite <select id="layoutPage">${snapshot.pages.map((p,i)=>`<option value="${i}">${p.page}</option>`).join('')}</select></label><button type="button" id="layoutAdd" class="secondary">Textfeld ergänzen</button><button type="button" id="layoutRefresh" class="secondary">Vorschau aktualisieren</button></div><div class="layout-comparison"><div><h3>Original</h3><div class="layout-sheet"><img id="layoutOriginal" alt="Originalseite"></div></div><div><h3>Übersetzung</h3><div class="layout-sheet" id="translatedSheet"><img id="layoutPreview" alt="Übersetzungsvorschau"><div id="layoutBoxes"></div></div></div></div><p id="layoutStatus" class="small-note" role="status">Vorschau wird erstellt …</p><div id="layoutWarnings" class="info-box" hidden></div><label class="field-label">Textfeld</label><select id="layoutBlock"></select><div id="layoutFields"></div><p class="small-note">Hintergründe werden in Textbereichen mit einer passenden Vollfarbe überdeckt. Muster und Stempel in diesen Bereichen können betroffen sein. „Original behalten“ lässt den betreffenden Bereich unverändert. ${snapshot.cost?'Gemeldete API-Kosten: $'+snapshot.cost.toFixed(4):''}</p>`;
  const release=()=>{urls.forEach(URL.revokeObjectURL);urls=[];};
  function page(){return snapshot.pages[pi];}
  function readFields(){if(selected<0)return;const b=page().blocks[selected];if(!$('#layoutEditText'))return;b.text=$('#layoutEditText').value;b.enabled=$('#layoutEnabled').checked;b.size=+$('#layoutSize').value;b.align=$('#layoutAlign').value;b.color=$('#layoutColor').value;b.background=$('#layoutAutoBackground').checked?'auto':$('#layoutBackground').value;
   const x=+$('#layoutX').value,y=+$('#layoutY').value,w=+$('#layoutW').value,h=+$('#layoutH').value;b.rect=[x,y,x+w,y+h];
   const sx=+$('#layoutSX').value,sy=+$('#layoutSY').value,sw=+$('#layoutSW').value,sh=+$('#layoutSH').value;b.sourceRect=[sx,sy,sx+sw,sy+sh];}
  function pick(i){readFields();selected=i;const b=page().blocks[i];$('#layoutBlock').value=i;
   if(!b){$('#layoutFields').innerHTML='';return;}
   const numbers=(r,prefix)=>[['X',r[0],'Links'],['Y',r[1],'Oben'],['W',r[2]-r[0],'Breite'],['H',r[3]-r[1],'Höhe']].map(([key,value,label])=>`<label><span class="field-label">${label} (pt)</span><input id="layout${prefix}${key}" type="number" min="0" step="0.1" value="${value.toFixed(1)}"></label>`).join('');
   $('#layoutFields').innerHTML=`<div class="two-columns"><label><span class="field-label">Erkanntes Original</span><textarea readonly rows="4">${esc(b.source)}</textarea></label><label><span class="field-label">Übersetzung korrigieren</span><textarea id="layoutEditText" rows="4">${esc(b.text)}</textarea></label></div><label class="check"><input id="layoutEnabled" type="checkbox" ${b.enabled?'checked':''}> Diesen Bereich übersetzen (aus = Original behalten)</label><div class="layout-coordinates">${numbers(b.rect,'')}</div><details><summary>Überdeckter Originalbereich anpassen</summary><div class="layout-coordinates">${numbers(b.sourceRect,'S')}</div></details><div class="layout-coordinates"><label><span class="field-label">Schriftgröße</span><input id="layoutSize" type="number" min="6" max="48" step="0.5" value="${b.size}"></label><label><span class="field-label">Ausrichtung</span><select id="layoutAlign"><option value="left">Links</option><option value="center">Mitte</option><option value="right">Rechts</option></select></label><label><span class="field-label">Textfarbe</span><input id="layoutColor" type="color" value="${b.color}"></label><label><span class="field-label">Hintergrund</span><input id="layoutBackground" type="color" value="${b.background==='auto'?'#ffffff':b.background}"></label></div><label class="check"><input id="layoutAutoBackground" type="checkbox" ${b.background==='auto'?'checked':''}> Hintergrundfarbe aus dem Original ermitteln</label><button type="button" id="layoutApply" class="secondary">Änderungen in Vorschau übernehmen</button>`;
   $('#layoutAlign').value=b.align;$('#layoutApply').onclick=()=>paint();showBoxes();
  }
  function options(){const select=$('#layoutBlock');select.replaceChildren();page().blocks.forEach((b,i)=>{const option=document.createElement('option');option.value=i;option.textContent=`${i+1} · ${b.enabled?'Übersetzen':'Original'} · ${b.source.slice(0,70)||'Manueller Text'}`;select.append(option);});}
  function showBoxes(){const layer=$('#layoutBoxes');if(!layer)return;layer.replaceChildren();page().blocks.forEach((b,i)=>{const rect=b.rect,button=document.createElement('button');button.type='button';button.className='layout-hit'+(i===selected?' selected':'')+(b.enabled?'':' preserved');button.style.cssText=`left:${rect[0]/page().width*100}%;top:${rect[1]/(page().height+24)*100}%;width:${(rect[2]-rect[0])/page().width*100}%;height:${(rect[3]-rect[1])/(page().height+24)*100}%`;button.title=`Textfeld ${i+1}: ${b.source}`;button.setAttribute('aria-label',button.title);button.onclick=()=>pick(i);layer.append(button);});}
  async function paint(){readFields();options();$('#layoutBlock').value=selected;const seq=++renderSeq;$('#layoutStatus').textContent='Vorschau wird lokal berechnet …';$('#dialogConfirm').disabled=true;
   try{const result=await rpc('translatedDocument',{pages:[page()],target:snapshot.target,preview:true});if(seq!==renderSeq||!$('#layoutPreview'))return;shown=result;release();const originalURL=URL.createObjectURL(new Blob([page().image],{type:'image/png'})),previewURL=URL.createObjectURL(new Blob([result.image],{type:'image/png'}));urls=[originalURL,previewURL];$('#layoutOriginal').src=originalURL;$('#layoutPreview').src=previewURL;showBoxes();
    const warnings=[...page().warnings,...result.issues.map(x=>`Textfeld ${page().blocks.findIndex(b=>b.id===x.id)+1}: ${x.message}`)];$('#layoutWarnings').hidden=!warnings.length;$('#layoutWarnings').textContent=warnings.join('\n');$('#layoutStatus').textContent=result.issues.some(x=>x.severity==='error')?'Einige Texte passen noch nicht. Bitte Felder vergrößern, Schrift verkleinern oder Original behalten.':'Vorschau aktualisiert. Textfelder und Angaben mit dem Original vergleichen.';
   }catch(e){if($('#layoutStatus'))$('#layoutStatus').textContent=e.message;shown=null;}
   finally{if(seq===renderSeq&&$('#dialog').open)$('#dialogConfirm').disabled=false;}
  }
  let answer;
  try{answer=await dialog('Layout-Übersetzung prüfen',body,{wide:true,confirm:snapshot.complete?'Übersetzte PDF herunterladen':'Teilübersetzung herunterladen',cancel:'Entwurf behalten',beforeClose:readFields,setup(){
   $('#dialog').classList.add('dialog-layout');$('#layoutBlock').onchange=e=>pick(+e.target.value);$('#layoutPage').onchange=e=>{readFields();pi=+e.target.value;selected=-1;$('#layoutFields').replaceChildren();options();pick(0);paint();};$('#layoutRefresh').onclick=()=>paint();
   $('#layoutAdd').onclick=()=>{readFields();const p=page(),id='manual-'+Date.now();p.blocks.push({id,source:'Manuell ergänzter Bereich',text:'Übersetzung hier eingeben',sourceRect:[p.width*.1,p.height*.1,p.width*.8,p.height*.17],rect:[p.width*.1,p.height*.1,p.width*.8,p.height*.17],size:12,align:'left',color:'#222222',background:'auto',enabled:true});options();pick(p.blocks.length-1);paint();};
   options();pick(0);paint();
  }});}finally{renderSeq++;release();$('#dialog').classList.remove('dialog-layout');$('#dialogConfirm').disabled=false;}
  if(!answer)return;
  let failed=false;await run(async()=>{const result=await rpc('translatedDocument',{pages:snapshot.pages,target:snapshot.target});const errors=result.issues.filter(x=>x.severity==='error');if(errors.length){failed=true;throw Error(`${errors.length} Textfeld(er) passen noch nicht. Kein Export erstellt. Bitte in der Vorschau korrigieren.`);}const suffix=snapshot.complete?'uebersetzt':'teiluebersetzung';download(result.bytes,`${snapshot.name}-${snapshot.target}-${suffix}.pdf`);toast('Übersetzte PDF erstellt. Original und Übersetzung gemeinsam aufbewahren.');},'Übersetzte PDF wird lokal erstellt …');
  if(failed)await review();
 }
 return {start,review,clear(){draft=null;},hasDraft:()=>!!draft?.pages.length};
}
